import type { RenderFieldV010 } from "../../runtime/contracts.js";
import { toRenderModel } from "../../runtime/render-model.js";
function esc(v:unknown){return String(v??"").replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#39;");}
function input(f:RenderFieldV010){const common=[`name="${esc(f.inputName)}"`,`data-semantic-type="${esc(f.semanticType)}"`,f.required?"required":"",f.readOnly?"disabled":""].filter(Boolean).join(" "); if(f.control==="select")return `<select ${common}>${(f.options??[]).map(o=>`<option data-value-type="${typeof o.value}" value="${esc(o.value)}">${esc(o.label)}</option>`).join("")}</select>`; const type=f.control==="number"||f.control==="money"?"number":f.control==="date"?"date":"text"; const min=f.validation?.min!==undefined?` min="${esc(f.validation.min)}"`:"";const max=f.validation?.max!==undefined?` max="${esc(f.validation.max)}"`:"";const pattern=f.validation?.pattern?` pattern="${esc(f.validation.pattern)}"`:"";return `<input type="${type}" ${common}${min}${max}${pattern}>${f.unit?`<span data-unit>${esc(f.unit)}</span>`:""}`;}
export function renderToHtml(document:unknown){const m=toRenderModel(document);const fields=m.fields.map(f=>`<label>${esc(f.label)}${input(f)}</label>`).join("");const cancels=m.cancelActions.map(a=>`<button type="button" data-eidos-action="${esc(a.id)}">${esc(a.label)}</button>`).join("");return `<form data-eidos-id="${esc(m.id)}" data-command="${esc(m.command.code)}" data-model-version="${m.modelVersion}"><h1>${esc(m.title)}</h1>${fields}<button type="submit" data-eidos-action="${esc(m.submitAction.id)}">${esc(m.submitAction.label)}</button>${cancels}</form>`;}
